def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [[0] * (V + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for v in range(V + 1):
            if i == 0 or v == 0:
                dp[i][v] = 0
            elif volumes[i - 1] > v:
                dp[i][v] = dp[i - 1][v]
            else:
                dp[i][v] = max(dp[i - 1][v], dp[i - 1][v - volumes[i - 1]] + volumes[i - 1])
    return V - dp[n][V]

def find_most_unhappy_day(schedule: list[tuple[int, int]]) -> int:
    # Initialize variables
    max_unhappiness = 0
    most_unhappy_day = 0

    # Iterate over the schedule
    for day, (school_hours, extra_class_hours) in enumerate(schedule, 1):
        total_hours = school_hours + extra_class_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day

    return most_unhappy_day

